async function saveContactMessage(formData: FormData) {
  'use server'

  const name = (formData.get('name') as string | null)?.trim() ?? ''
  const email = (formData.get('email') as string | null)?.trim() ?? ''
  const message = (formData.get('message') as string | null)?.trim() ?? ''

  // Server-side validation: every field must be provided.
  if (!name || !email || !message) {
    throw new Error('All fields (name, email, and message) are required.')
  }

  // Simulate persisting the contact message.
  console.log('Saving contact message:', { name, email, message })

  return { success: true }
}

export default function ContactForm() {
  return (
    <div>
      <h2>Contact Us</h2>
      <form action={saveContactMessage}>
        <div>
          <label htmlFor="name">Name</label>
          <input id="name" name="name" type="text" placeholder="Your name" required />
        </div>
        <div>
          <label htmlFor="email">Email</label>
          <input id="email" name="email" type="email" placeholder="you@example.com" required />
        </div>
        <div>
          <label htmlFor="message">Message</label>
          <textarea id="message" name="message" placeholder="Your message" required />
        </div>
        <button type="submit">Send Message</button>
      </form>
    </div>
  )
}

